6	// ROT13 decode function
7	function rot13(text: string): string {
8	  return text.replace(/[a-zA-Z]/g, (char) => {
9	    const base = char <= "Z" ? 65 : 97;
10	    return String.fromCharCode(((char.charCodeAt(0) - base + 13) % 26) + base);
11	  });
12	}
